// Loop over input items and add a new field called 'myNewField' to the JSON of each one

const registros = $input.all();

const tickets = registros
  .filter(item => item.json.fields?.Codigo_Ticket)
  .map(item => ({
    ticket_id: item.json.fields.Codigo_Ticket,
    record_id: item.json.id,
    estado: item.json.fields.Estado ?? "",
    descripcion: item.json.fields.Descripcion ?? "",
    prioridad: item.json.fields.Prioridad ?? ""
  }));

return [{
  json: {
    ok: true,
    accion: "buscar",
    tipo: "listado",
    cantidad: tickets.length,
    tickets: tickets,
    mensaje: tickets.length > 0
      ? `Se encontraron ${tickets.length} tickets.`
      : "No se encontraron tickets para este contacto."
  }
}];
